def compute(vars):
    x0 = vars["100"]
    x1 = vars["Resulting Number"]
    x2 = vars["Starting Number"]

    if x0 is None or x1 is None or x2 is None or x2 == 0:
        return None

    percentage_change = x0 * (x1 - x2) / x2

    return {
        "value": percentage_change,
        "trace": {
            "100": x0,
            "Resulting Number": x1,
            "Starting Number": x2,
            "difference": x1 - x2,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
